/**
 * Strips trailing incomplete Markdown list-marker lines so incremental
 * `ReactMarkdown` parses do not emit empty list items while streaming.
 *
 * Matches CommonMark-style list starts: up to 3 leading spaces, then
 * `-` / `*` / `+` or ordered `digits.`, with only whitespace after the marker
 * (or end of line immediately after unordered marker).
 */
const LONE_LIST_MARKER_LINE =
  /^\s{0,3}(?:[-*+](?:\s|$)|\d+\.(?:\s|$))\s*$/;

function stripTrailingLoneListLines(markdown: string): string {
  let result = markdown.replace(/\r\n/g, "\n");
  const lines = result.split("\n");

  while (lines.length > 0) {
    const last = lines[lines.length - 1];
    if (last !== undefined && LONE_LIST_MARKER_LINE.test(last)) {
      lines.pop();
      continue;
    }
    break;
  }

  result = lines.join("\n");
  return result;
}

/**
 * @param markdown - raw assistant markdown buffer while streaming
 */
export function prepareStreamingMarkdown(markdown: string): string {
  if (!markdown) return markdown;
  return stripTrailingLoneListLines(markdown);
}
