import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useEffect, useRef } from 'react';
import { useAuthContext } from '@/contexts/AuthContext';
import { 
  projectAPI, 
  Project, 
  ProjectsResponse, 
  CreateProjectPayload, 
  UpdateProjectPayload 
} from '@/services/api/api';

export const useProjects = () => {
  const queryClient = useQueryClient();
  const lastActiveProjectIdRef = useRef<string>('');
  const { isAuthenticated } = useAuthContext();
  const isWidgetMode =
    typeof window !== 'undefined' && !!(window as any).RAGSUITE_PROJECT_ID;
  const widgetProjectId = isWidgetMode
    ? String((window as any).RAGSUITE_PROJECT_ID || '')
    : '';

  const hasCORBError = typeof window !== 'undefined' && (window as any).__HAS_CORB_CORS_ERROR;

  const projectsQuery = useQuery({
    queryKey: ['projects'],
    queryFn: projectAPI.getProjects,
    enabled: isAuthenticated && !isWidgetMode,
    staleTime: 300000, // 5 minutes - projects don't change frequently
    refetchInterval: false,
    refetchOnWindowFocus: false,
    retry: 1,
    retryDelay: 2000,
  });

  useEffect(() => {
    if (projectsQuery.error) {
      const error: any = projectsQuery.error;
      const isCORBError = error.message?.includes('CORB') || error.message?.includes('Cross-Origin');
      const isCORSError = error.code === 'ERR_NETWORK' || error.message?.includes('CORS') || error.message?.includes('blocked');
      if ((isCORBError || isCORSError) && typeof window !== 'undefined') {
        (window as any).__HAS_CORB_CORS_ERROR = true;
      }
    }
  }, [projectsQuery.error]);

  const createProjectMutation = useMutation({
    mutationFn: (payload: CreateProjectPayload) =>
      projectAPI.createProject(payload),
    
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['projects'] });
    },
    
    onError: (error) => {
      console.error('❌ Create project failed:', error);
    },
  });

  const updateProjectMutation = useMutation({
    mutationFn: ({ id, payload }: { id: string; payload: UpdateProjectPayload }) =>
      projectAPI.updateProject(id, payload),
    
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['projects'] });
    },
    
    onError: (error) => {
      console.error('❌ Update project failed:', error);
    },
  });

  const deleteProjectMutation = useMutation({
    mutationFn: (id: string) => projectAPI.deleteProject(id),
    
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['projects'] });
    },
    
    onError: (error) => {
      console.error('❌ Delete project failed:', error);
    },
  });

  const activateProjectMutation = useMutation({
    mutationFn: (id: string) => projectAPI.activateProject(id),
    
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['projects'] });
    },
    
    onError: (error) => {
      console.error('❌ Activate project failed:', error);
    },
  });

  const projects = isWidgetMode ? [] : (projectsQuery.data?.projects || []);
  const activeProjectId =
    widgetProjectId ||
    projectsQuery.data?.active_project_id ||
    projects.find((project) => project.is_active)?.id ||
    '';

  useEffect(() => {
    if (!activeProjectId) return;
    if (!lastActiveProjectIdRef.current) {
      lastActiveProjectIdRef.current = activeProjectId;
      return;
    }
    if (lastActiveProjectIdRef.current === activeProjectId) return;

    // Project switch: force refresh project-scoped caches to avoid stale UI from previous project.
    const previousProjectId = lastActiveProjectIdRef.current;
    lastActiveProjectIdRef.current = activeProjectId;
    const projectScopedKeys: ReadonlyArray<readonly unknown[]> = [
      ['prompt', previousProjectId],
      ['prompt', activeProjectId],
      ['search-prompt', previousProjectId],
      ['search-prompt', activeProjectId],
      ['chatbot-settings', previousProjectId],
      ['chatbot-settings', activeProjectId],
      ['config-models', previousProjectId],
      ['config-models', activeProjectId],
      ['search-config-models', previousProjectId],
      ['search-config-models', activeProjectId],
      ['chatbot-activation', previousProjectId],
      ['chatbot-activation', activeProjectId],
      ['search-activation', previousProjectId],
      ['search-activation', activeProjectId],
      ['model-profiles', previousProjectId],
      ['model-profiles', activeProjectId],
    ];
    projectScopedKeys.forEach((key) => {
      queryClient.removeQueries({ queryKey: key, exact: true });
      queryClient.invalidateQueries({ queryKey: key, exact: true });
    });
  }, [activeProjectId, queryClient]);

  return {
    projects,
    total: projectsQuery.data?.total || 0,
    activeProjectId,
    isLoading: projectsQuery.isLoading,
    isRefetching: projectsQuery.isRefetching,
    error: projectsQuery.error,
    refetch: projectsQuery.refetch,
    
    createProject: createProjectMutation.mutate,
    createProjectAsync: createProjectMutation.mutateAsync,
    isCreating: createProjectMutation.isPending,
    createError: createProjectMutation.error,
    
    updateProject: updateProjectMutation.mutate,
    updateProjectAsync: updateProjectMutation.mutateAsync,
    isUpdating: updateProjectMutation.isPending,
    updateError: updateProjectMutation.error,
    
    deleteProject: deleteProjectMutation.mutate,
    deleteProjectAsync: deleteProjectMutation.mutateAsync,
    isDeleting: deleteProjectMutation.isPending,
    deleteError: deleteProjectMutation.error,
    
    activateProject: activateProjectMutation.mutate,
    activateProjectAsync: activateProjectMutation.mutateAsync,
    isActivating: activateProjectMutation.isPending,
    activateError: activateProjectMutation.error,
  };
};

export const useProject = (projectId: string) => {
  const projectQuery = useQuery({
    queryKey: ['project', projectId],
    queryFn: () => projectAPI.getProject(projectId),
    enabled: !!projectId,
    staleTime: 30000,
  });

  return {
    project: projectQuery.data,
    isLoading: projectQuery.isLoading,
    error: projectQuery.error,
    refetch: projectQuery.refetch,
  };
};
