
import React from "react";
import { createRoot } from "react-dom/client";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { EmbeddableWidget } from "./components/common/EmbeddableWidget";
import { RAGSettingsProvider } from "./contexts/RAGSettingsContext";
import { BrandingProvider } from "./contexts/BrandingContext";
import { ThemeProvider } from "./contexts/ThemeContext";
import { AuthProvider } from "./contexts/AuthContext";
import { I18nProvider, useTranslation } from "./contexts/I18nContext";
import { useChatbotActivation } from "./hooks/useChatbotActivation";
import { getWidgetAssetOrigin, resolveBrowserApiBaseUrl } from "./utils/publicApiBaseUrl";
import "./styles/index.css";
import "./components/common/WidgetTailwindScope.css";
import "./components/common/EmbeddableWidgetStyles.css";

const widgetQueryClient = new QueryClient({
  defaultOptions: {
    queries: {
      refetchOnWindowFocus: false,
      refetchOnMount: true,
      staleTime: 5 * 60 * 1000,
      retry: 1,
    },
    mutations: {
      retry: 1,
    },
  },
});

interface WidgetConfig {
  projectId: string;
  
  apiEndpoint?: string;
  
  position?: "bottom-right" | "bottom-left" | "top-right" | "top-left";
  
  zIndex?: number;
  
  primaryColor?: string;
  
  title?: string;
  
  welcomeMessage?: string;
  
  orgName?: string;
  
  chatbotTitle?: string;
  
  widgetLogoUrl?: string;
  
  widgetAvatar?: string;
  
  widgetShowLogo?: boolean;
  
  widgetShowDateTime?: boolean;
  
  widgetBottomSpace?: number;
  
  widgetFontSize?: number;
  
  widgetTriggerBorderRadius?: number;
  
  widgetOffsetX?: number;
  
  widgetOffsetY?: number;

  exclusive?: boolean;
  exclusivePriority?: number;
  embedToken?: string;
}

let widgetInstance: {
  root: any;
  container: HTMLElement;
} | null = null;

const getRegistry = (): {
  chatbot?: { priority: number; destroy: () => void };
} => {
  if (!(window as any).__RAGSUITE_WIDGET_REGISTRY__) {
    (window as any).__RAGSUITE_WIDGET_REGISTRY__ = {};
  }
  return (window as any).__RAGSUITE_WIDGET_REGISTRY__;
};

let API_BASE_URL = "";

/**
 * Initialize Widget
 * 
 * This function:
 * 1. Creates a container element in the page
 * 2. Creates a React root
 * 3. Renders the EmbeddableWidget component
 * 4. Sets up API configuration
 * 
 * @param config - Widget configuration options
 */
function initWidget(config: WidgetConfig) {
  if (!config.projectId) {
    console.error("RAG Suite Widget: projectId is required. Please provide a valid project ID.");
    return;
  }

  const registry = getRegistry();
  const exclusive = config.exclusive !== false;
  const priority = config.exclusivePriority ?? 0;
  
  if (widgetInstance) {
    const currentProjectId = (window as any).RAGSUITE_PROJECT_ID;
    if (currentProjectId && currentProjectId !== config.projectId) {
      destroyWidget();
    } else if (currentProjectId === config.projectId) {
      console.warn("RAG Suite Widget: Already initialized with same project ID. Use destroy() first to reinitialize.");
      return;
    } else {
      destroyWidget();
    }
  }

  if (exclusive && registry.chatbot) {
    if (priority < registry.chatbot.priority) {
      console.warn("RAG Suite Widget: Skipping init due to existing chatbot widget with higher priority.");
      return;
    }
    registry.chatbot.destroy();
  }

  const assetOrigin = getWidgetAssetOrigin();
  if (assetOrigin) {
    (window as any).RAGSUITE_ASSET_ORIGIN = assetOrigin;
  }

  API_BASE_URL = resolveBrowserApiBaseUrl(config.apiEndpoint, {
    pageOrigin: window.location.origin,
    assetOrigin,
  });

  const getCurrentDomain = (): string | null => {
    try {
      if (typeof window !== 'undefined') {
        const hostname = window.location.hostname;
        return hostname.split(':')[0];
      }
    } catch (e) {
      console.warn('RAG Suite Widget: Could not extract domain:', e);
    }
    return null;
  };

  const currentDomain = getCurrentDomain();
  if (currentDomain) {
    (window as any).RAGSUITE_CURRENT_DOMAIN = currentDomain;
  }

  const hostElement = document.createElement("div");
  hostElement.id = "ragsuite-widget-host";
  
  hostElement.style.cssText = `
    position: fixed !important;
    z-index: 2147483647 !important;
    left: 0 !important;
    top: 0 !important;
    width: 100vw !important;
    height: 100vh !important;
    pointer-events: none !important;
    overflow: visible !important;
    margin: 0 !important;
    padding: 0 !important;
    border: none !important;
    background: transparent !important;
    box-sizing: border-box !important;
    isolation: isolate !important;
    contain: layout style paint !important;
    all: initial !important;
    font-family: inherit !important;
    font-size: inherit !important;
    line-height: inherit !important;
  `;
  
  hostElement.setAttribute('data-ragsuite-widget', 'chatbot');

  document.body.appendChild(hostElement);

  const shadow = hostElement.attachShadow({ 
    mode: 'open',
    delegatesFocus: false
  });

  const cssUrl = `${API_BASE_URL}/widget/v1/widget.css`;
  
  const link = document.createElement("link");
  link.rel = "stylesheet";
  link.href = cssUrl;
  link.onerror = () => {
    console.warn("⚠️ RAG Suite Widget: Failed to load CSS from", cssUrl);
  };
  shadow.appendChild(link);

  const container = document.createElement("div");
  container.id = "ragsuite-widget-container";
  container.className = "ragsuite-widget-root ragsuite-widget-scope";
  
  container.style.cssText = `
    width: 100% !important;
    height: 100% !important;
    pointer-events: none !important;
    margin: 0 !important;
    padding: 0 !important;
    border: none !important;
    box-sizing: border-box !important;
    isolation: isolate !important;
    contain: layout style paint !important;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen', 'Ubuntu', 'Cantarell', sans-serif !important;
    font-size: 16px !important;
    line-height: 1.5 !important;
  `;
  
  container.setAttribute('data-ragsuite-widget-container', 'chatbot');
  
  shadow.appendChild(container);

  (window as any).RAGSUITE_API_URL = API_BASE_URL;
  (window as any).RAGSUITE_PROJECT_ID = config.projectId;
  if (config.embedToken) {
    (window as any).RAGSUITE_EMBED_TOKEN = config.embedToken;
  }

  const root = createRoot(container);

  const WidgetWrapper = () => {
    const [isOpen, setIsOpen] = React.useState(false);
    const { t } = useTranslation();
    
    const { isActive: isChatbotActive, isLoading: isActivationLoading, activationData } = useChatbotActivation();
    
    const handleToggle = React.useCallback(() => {
      setIsOpen(prev => !prev);
    }, []);
    
    
    React.useEffect(() => {
      const widgetHost = document.getElementById('ragsuite-widget-host');
      if (widgetHost) {
        if (!isChatbotActive || isActivationLoading) {
          widgetHost.style.display = 'none';
          widgetHost.style.visibility = 'hidden';
          widgetHost.style.opacity = '0';
          widgetHost.style.pointerEvents = 'none';
        } else {
          widgetHost.style.display = 'block';
          widgetHost.style.visibility = 'visible';
          widgetHost.style.opacity = '1';
          widgetHost.style.pointerEvents = 'none'; 
          
          if (isChatbotActive) {
          } else {
          }
        }
      }
    }, [isChatbotActive, isActivationLoading, activationData]);
    
    
    if (isActivationLoading || !isChatbotActive) {
      return null;
    }
    
    return (
      <EmbeddableWidget
        isOpen={isOpen}
        onToggle={handleToggle}
        title={t("widget.chat.title")}
        previewOverrides={undefined}
        onReady={() => {
          window.dispatchEvent(new CustomEvent("ragsuite:ready"));
        }}
        onError={(error) => {
          console.error("RAG Suite Widget: Error occurred", error);
          window.dispatchEvent(
            new CustomEvent("ragsuite:error", { detail: error })
          );
        }}
      />
    );
  };

  root.render(
    <QueryClientProvider client={widgetQueryClient}>
      <I18nProvider>
        <AuthProvider>
          <RAGSettingsProvider>
            <BrandingProvider>
              <ThemeProvider>
                <WidgetWrapper />
              </ThemeProvider>
            </BrandingProvider>
          </RAGSettingsProvider>
        </AuthProvider>
      </I18nProvider>
    </QueryClientProvider>
  );

  widgetInstance = { root, container: hostElement };
  if (exclusive) {
    registry.chatbot = { priority, destroy: destroyWidget };
  }

  const widgetHost = document.getElementById("ragsuite-widget-host");
  if (widgetHost) {
    if (widgetHost.shadowRoot) {
    }
  } else {
    console.error("❌ Widget host not found in DOM!");
  }
}

function destroyWidget() {
  if (widgetInstance) {
    widgetInstance.root.unmount();
    widgetInstance.container.remove();
    widgetInstance = null;

    const registry = getRegistry();
    if (registry.chatbot?.destroy === destroyWidget) {
      delete registry.chatbot;
    }
    
    Object.keys(window).forEach(key => {
      if (key.startsWith('__RAGSUITE_INIT_EXECUTED_')) {
        try {
          delete (window as any)[key];
        } catch (e) {
        }
      }
    });
    
    if ((window as any).RAGSUITE_PROJECT_ID) {
      delete (window as any).RAGSUITE_PROJECT_ID;
    }
    
    window.dispatchEvent(new CustomEvent("ragsuite:destroyed"));
  }
}

declare global {
  interface Window {
    RAGSuiteWidget: {
      init: (config: WidgetConfig) => void;
      destroy: () => void;
      version: string;
    };
  }
}

window.RAGSuiteWidget = {
  init: initWidget,
  destroy: destroyWidget,
  version: "1.0.0",
};
