
/** Normalize FastAPI / axios error bodies to a single string. */
export function normalizeErrorDetail(detail: unknown): string {
  if (typeof detail === "string") {
    return detail.trim();
  }
  if (Array.isArray(detail)) {
    const parts = detail
      .map((item) => {
        if (typeof item === "string") return item;
        if (item && typeof item === "object" && "msg" in item) {
          return String((item as { msg?: string }).msg ?? "");
        }
        return "";
      })
      .filter(Boolean);
    return parts.join("; ");
  }
  return "";
}

function getErrorDetailString(error: any): string {
  const data = error?.response?.data;
  return (
    normalizeErrorDetail(data?.detail) ||
    (typeof data?.error === "string" ? data.error.trim() : "") ||
    normalizeErrorDetail(data?.message) ||
    (typeof error?.message === "string" ? error.message.trim() : "")
  );
}

function isExplicitApiKeyErrorText(text: string): boolean {
  const lower = text.toLowerCase();
  return (
    lower.includes("api key") ||
    lower.includes("apikey") ||
    lower.includes("api_key") ||
    lower.includes("invalid key") ||
    lower.includes("expired key") ||
    lower.includes("missing key")
  );
}

export type ResolveChatErrorOptions = {
  /** Public embed on a customer site (not dashboard preview). */
  isWidgetEmbed?: boolean;
  defaultMessage?: string;
};

/**
 * Map HTTP / network failures to user-facing chat messages.
 * Status and server detail take precedence over API-key keyword guessing.
 */
export function resolveChatErrorMessage(
  error: unknown,
  options: ResolveChatErrorOptions = {},
): string {
  const defaultMessage =
    options.defaultMessage ??
    "Sorry, I encountered an error while chatting. Please try again.";

  if (!error || typeof error !== "object") {
    return defaultMessage;
  }

  const err = error as Record<string, unknown>;
  const status =
    err.response && typeof err.response === "object"
      ? (err.response as { status?: number }).status
      : undefined;
  const detail = getErrorDetailString(err);
  const detailLower = detail.toLowerCase();
  const message = typeof err.message === "string" ? err.message : "";
  const messageLower = message.toLowerCase();

  if (status === 401) {
    if (options.isWidgetEmbed) {
      if (detail && !isExplicitApiKeyErrorText(detail)) {
        return detail;
      }
      return "This chat is not available right now. Please try again later.";
    }
    if (detail && isExplicitApiKeyErrorText(detail)) {
      return "Please enter a valid API key";
    }
    return detail || "Authentication failed. Please check your credentials.";
  }

  if (status === 429) {
    if (detailLower.includes("concurrent") || messageLower.includes("concurrent")) {
      return (
        "The AI service is handling too many requests at once. " +
        "Please wait a moment and try again."
      );
    }
    return "You're sending messages too fast. Please wait a moment and try again.";
  }

  if (
    messageLower.includes("429") ||
    messageLower.includes("too many concurrent") ||
    messageLower.includes("rate limit")
  ) {
    if (messageLower.includes("concurrent")) {
      return (
        "The AI service is handling too many requests at once. " +
        "Please wait a moment and try again."
      );
    }
    return "You're sending messages too fast. Please wait a moment and try again.";
  }

  if (status === 503) {
    return "The AI service is currently unavailable. Please try again in a few minutes.";
  }

  if (status === 403) {
    if (detail) {
      return detail;
    }
    return "Domain validation failed. Please add this domain to your allowed domains in Settings > Allowed Domains.";
  }

  if (status === 400 && detail) {
    return detail;
  }

  if (status !== undefined && status >= 500) {
    return detail || "Server Error: The chat server is experiencing issues. Please try again later.";
  }

  if (
    messageLower.includes("failed to fetch") ||
    messageLower.includes("network error") ||
    messageLower.includes("err_network") ||
    err.code === "ERR_NETWORK"
  ) {
    return "We couldn't connect to the server. Please check your internet connection and try again.";
  }

  if (messageLower.includes("cors")) {
    return "CORS Error: The server is blocking requests. Please check server CORS configuration.";
  }

  if (messageLower.includes("timeout") || err.name === "AbortError") {
    return "Connection Timeout: The chat server is not responding. Please check if the server is running.";
  }

  if (detail) {
    const isDomainIssue =
      detailLower.includes("domain") ||
      detailLower.includes("allowed domain") ||
      detailLower.includes("domain validation") ||
      detailLower.includes("authorized for this project");

    if (isDomainIssue) {
      return detail;
    }

    if (!options.isWidgetEmbed && isExplicitApiKeyErrorText(detail)) {
      if (detailLower.includes("missing") || detailLower.includes("required")) {
        return "Please enter the API key";
      }
      if (detailLower.includes("expired")) {
        return "API key has expired. Please enter a valid API key";
      }
      return "Please enter a valid API key";
    }

    return detail;
  }

  if (message && !messageLower.includes("stream request failed")) {
    return message;
  }

  return defaultMessage;
}

/** Sanitize streamed assistant text when the backend/LLM sent a raw provider error. */
export function mapStreamErrorContent(text: string): string {
  const trimmed = text.trim();
  if (!trimmed) {
    return "Something went wrong. Please try again.";
  }

  const withoutPrefix = trimmed.replace(/^error:\s*/i, "").trim();
  const lower = withoutPrefix.toLowerCase();

  if (
    lower.includes("429") ||
    lower.includes("rate limit") ||
    lower.includes("too many concurrent") ||
    lower.includes("too many requests")
  ) {
    if (lower.includes("concurrent")) {
      return (
        "The AI service is handling too many requests at once. " +
        "Please wait a moment and try again."
      );
    }
    return "You're sending messages too fast. Please wait a moment and try again.";
  }

  if (lower.includes("503") || lower.includes("overloaded") || lower.includes("service unavailable")) {
    return "The AI service is temporarily unavailable. Please try again in a few minutes.";
  }

  if (lower.startsWith("error:") || lower.includes("status code:")) {
    return "Sorry, I couldn't generate a response. Please try again.";
  }

  return trimmed;
}

/**
 * Get user-friendly error message for API key issues (settings / dashboard forms).
 */
export function getUserFriendlyApiKeyErrorMessage(
  error: any,
  defaultMessage: string = "An error occurred",
): string {
  if (!error) {
    return defaultMessage;
  }

  const detail = getErrorDetailString(error);
  const errorString = detail.toLowerCase();
  const status = error?.response?.status;

  if (status === 403 && detail) {
    return detail;
  }

  if (status === 401) {
    if (isExplicitApiKeyErrorText(detail)) {
      return "Please enter a valid API key";
    }
    return detail || "Authentication failed. Please check your API key";
  }

  if (isExplicitApiKeyErrorText(errorString)) {
    if (errorString.includes("missing") || errorString.includes("required")) {
      return "Please enter the API key";
    }
    if (
      errorString.includes("invalid") ||
      errorString.includes("not valid") ||
      errorString.includes("incorrect")
    ) {
      return "Please enter a valid API key";
    }
    if (errorString.includes("expired")) {
      return "API key has expired. Please enter a valid API key";
    }
    return "Please enter a valid API key";
  }

  if (
    errorString.includes("domain") ||
    errorString.includes("allowed domain") ||
    errorString.includes("domain validation") ||
    errorString.includes("not authorized") ||
    errorString.includes("not allowed") ||
    errorString.includes("authorized for this project")
  ) {
    return (
      detail ||
      "Domain validation failed. Please add this domain to your allowed domains in Settings > Allowed Domains."
    );
  }

  if (detail) {
    return detail;
  }

  if (error?.message) {
    return error.message;
  }

  return defaultMessage;
}

/** True when the API returned the masked sentinel (first-4 + '...' + last-4). */
export function isMaskedApiKey(key: string | null | undefined): boolean {
  if (!key) return false;
  const trimmed = key.trim();
  return trimmed.includes("...") && trimmed.length <= 16;
}

/** Turn raw provider / LlamaIndex errors from connection tests into short user hints. */
export function formatConnectionTestError(raw: string): string {
  const text = raw.trim();
  if (!text) return "Connection failed. Please try again.";

  const lower = text.toLowerCase();

  if (
    lower.includes("status 401") ||
    lower.includes("401 unauthorized") ||
    lower.includes('"unauthorized"') ||
    lower.includes("incorrect api key") ||
    lower.includes("invalid api key") ||
    lower.includes("invalid_api_key") ||
    lower.includes("authentication_error")
  ) {
    return "Invalid API key. Check that the key matches the selected provider.";
  }

  if (lower.includes("status 403") || lower.includes("403 forbidden")) {
    return "Access denied. This API key may not have permission for the selected model.";
  }

  if (
    lower.includes("status 429") ||
    lower.includes("rate limit") ||
    lower.includes("too many requests")
  ) {
    return "Rate limit reached. Wait a moment and try again.";
  }

  if (lower.includes("timed out") || lower.includes("timeout")) {
    return "Connection timed out. Check your network and try again.";
  }

  if (lower.includes("status 503") || lower.includes("service unavailable")) {
    return "The provider is temporarily unavailable. Try again in a few minutes.";
  }

  const bodyMatch = text.match(/Body:\s*(\{.*\})/i);
  if (bodyMatch) {
    try {
      const body = JSON.parse(bodyMatch[1]) as { detail?: unknown; error?: unknown; message?: unknown };
      const detail =
        (typeof body.detail === "string" && body.detail) ||
        (typeof body.error === "string" && body.error) ||
        (typeof body.message === "string" && body.message);
      if (detail) return formatConnectionTestError(detail);
    } catch {
      // fall through
    }
  }

  if (text.length > 120) {
    return "Connection failed. Please verify your API key and model settings.";
  }

  return text.replace(/^Failed:\s*/i, "");
}

/**
 * Validate API key before saving
 */
export function validateApiKeyForSave(apiKey: string): { isValid: boolean; message?: string } {
  if (!apiKey || apiKey.trim() === "") {
    return { isValid: false, message: "Please enter the API key" };
  }

  const trimmedKey = apiKey.trim();

  if (trimmedKey.length < 20) {
    return { isValid: false, message: "API key must be at least 20 characters long" };
  }

  const apiKeyPattern = /^[a-zA-Z0-9\-_\.]+$/;
  if (!apiKeyPattern.test(trimmedKey)) {
    return {
      isValid: false,
      message:
        "API key contains invalid characters. Only letters, numbers, dashes, underscores, and dots are allowed",
    };
  }

  return { isValid: true };
}
