export const ADMIN_CHAT_DELETED_EVENT = "ragsuite:admin-chat-deleted";

export type AdminChatDeletedDetail = {
  sessionIds: string[];
  projectId?: string;
};

export function notifyAdminChatSessionsDeleted(
  sessionIds: string[],
  projectId?: string | null,
) {
  if (typeof window === "undefined" || sessionIds.length === 0) return;

  window.dispatchEvent(
    new CustomEvent<AdminChatDeletedDetail>(ADMIN_CHAT_DELETED_EVENT, {
      detail: {
        sessionIds,
        projectId: projectId ?? undefined,
      },
    }),
  );
}
