const DEV_FRONTEND_PORTS = new Set(["3000", "5173", "5174", "6173"]);
const DEFAULT_API_PATH = "/api/v1";
const DEV_BACKEND_PORT = "8000";

function trimTrailingSlash(value: string): string {
  return value.replace(/\/+$/, "");
}

function isPrivateOrLoopbackHostname(hostname: string): boolean {
  const host = String(hostname || "").toLowerCase().trim();
  if (!host) return false;
  if (host === "localhost" || host === "127.0.0.1" || host === "0.0.0.0" || host === "::1") {
    return true;
  }
  if (/^192\.168\.\d+\.\d+$/.test(host)) return true;
  if (/^10\.\d+\.\d+\.\d+$/.test(host)) return true;
  if (/^172\.(1[6-9]|2\d|3[01])\.\d+\.\d+$/.test(host)) return true;
  return false;
}

function coerceDevFrontendPort(url: URL): URL {
  if (!DEV_FRONTEND_PORTS.has(url.port || "")) {
    return url;
  }
  const next = new URL(url.toString());
  next.port = DEV_BACKEND_PORT;
  if (!next.pathname || next.pathname === "/") {
    next.pathname = DEFAULT_API_PATH;
  }
  return next;
}

function toAbsoluteUrl(raw: string, fallbackOrigin: string): URL | null {
  try {
    return new URL(raw, fallbackOrigin);
  } catch {
    return null;
  }
}

function rewriteApiUrlToOrigin(resolved: URL, origin: string, defaultPath: string): URL {
  const next = new URL(resolved.pathname || defaultPath, origin);
  if (!next.pathname || next.pathname === "/") {
    next.pathname = defaultPath;
  }
  return next;
}

function urlLooksPrivateOrDev(url: URL): boolean {
  return isPrivateOrLoopbackHostname(url.hostname) || DEV_FRONTEND_PORTS.has(url.port || "");
}

function urlLooksPublic(url: URL): boolean {
  return !isPrivateOrLoopbackHostname(url.hostname) && !DEV_FRONTEND_PORTS.has(url.port || "");
}

/** Infer the public origin that serves the widget loader/init script. */
export function inferWidgetScriptOrigin(): string | null {
  if (typeof document === "undefined" || typeof window === "undefined") {
    return null;
  }

  const scriptSelectors = [
    'script[data-ragsuite-project-id][src]',
    'script[src*="ragsuite-init.js"]',
    'script[src*="/widget/"][src*="loader.js"]',
    'script[src*="/search-widget/"][src*="loader.js"]',
  ];

  for (const selector of scriptSelectors) {
    const scripts = document.querySelectorAll<HTMLScriptElement>(selector);
    for (const script of Array.from(scripts)) {
      const src = (script.getAttribute("src") || script.src || "").trim();
      if (!src) continue;
      try {
        return trimTrailingSlash(new URL(src, window.location.href).origin);
      } catch {
        // try next script tag
      }
    }
  }

  return null;
}

export function resolveBrowserApiBaseUrl(
  rawCandidate?: string | null,
  options?: {
    pageOrigin?: string | null;
    assetOrigin?: string | null;
    defaultPath?: string;
  },
): string {
  const pageOrigin =
    options?.pageOrigin ||
    (typeof window !== "undefined" ? window.location.origin : "");
  const assetOrigin = options?.assetOrigin || inferWidgetScriptOrigin() || pageOrigin;
  const defaultPath = options?.defaultPath || DEFAULT_API_PATH;
  const fallbackOrigin = assetOrigin || pageOrigin || "http://localhost";
  const fallbackUrl = `${trimTrailingSlash(fallbackOrigin)}${defaultPath}`;
  const candidate = String(rawCandidate || "").trim() || fallbackUrl;

  let resolved = toAbsoluteUrl(candidate, fallbackOrigin);
  if (!resolved) {
    return fallbackUrl;
  }

  resolved = coerceDevFrontendPort(resolved);

  const preferredOriginUrl =
    toAbsoluteUrl(assetOrigin || "", fallbackOrigin) ||
    toAbsoluteUrl(pageOrigin || "", fallbackOrigin);
  const currentPageUrl = toAbsoluteUrl(pageOrigin || "", fallbackOrigin);

  if (urlLooksPrivateOrDev(resolved) && preferredOriginUrl && urlLooksPublic(preferredOriginUrl)) {
    resolved = rewriteApiUrlToOrigin(resolved, preferredOriginUrl.origin, defaultPath);
  }

  if (
    currentPageUrl?.protocol === "https:" &&
    resolved.protocol === "http:" &&
    preferredOriginUrl?.protocol === "https:"
  ) {
    resolved = rewriteApiUrlToOrigin(resolved, preferredOriginUrl.origin, defaultPath);
  }

  // Widget embeds must never open user-visible document links on LAN/dev hosts.
  const isWidgetEmbed =
    typeof window !== "undefined" && !!(window as any).RAGSUITE_PROJECT_ID;
  if (
    isWidgetEmbed &&
    preferredOriginUrl &&
    urlLooksPublic(preferredOriginUrl) &&
    urlLooksPrivateOrDev(resolved)
  ) {
    resolved = rewriteApiUrlToOrigin(resolved, preferredOriginUrl.origin, defaultPath);
  }

  return trimTrailingSlash(resolved.toString());
}

export function getWidgetAssetOrigin(): string | null {
  if (typeof window === "undefined") return null;
  const value =
    (window as any).RAGSUITE_ASSET_ORIGIN ||
    (window as any).RAGSUITE_SEARCH_WIDGET_ASSET_ORIGIN ||
    null;
  if (typeof value === "string" && value.trim()) {
    return trimTrailingSlash(value);
  }
  return inferWidgetScriptOrigin();
}

/** Runtime API base for widget + dashboard (prefers live widget config over build-time defaults). */
export function getRuntimeApiBaseUrl(fallbackCandidate?: string | null): string {
  const pageOrigin =
    typeof window !== "undefined" ? window.location.origin : "";
  const assetOrigin = getWidgetAssetOrigin();
  const widgetApi =
    typeof window !== "undefined" && (window as any).RAGSUITE_API_URL
      ? String((window as any).RAGSUITE_API_URL).trim()
      : "";

  const candidate = widgetApi || String(fallbackCandidate || "").trim();
  return resolveBrowserApiBaseUrl(candidate || null, {
    pageOrigin,
    assetOrigin,
  });
}

export function buildDocumentContentStreamUrl(documentId: string, token: string): string {
  const apiBase = getRuntimeApiBaseUrl();
  return `${apiBase}/documents/${documentId}/content-stream?token=${encodeURIComponent(token)}`;
}
