/** Phrases that mean the assistant refused — do not show misleading source links. */
const CHAT_CITATION_SUPPRESSION_PHRASES = [
  "out of the context of the provided documents",
  "out of the context",
  "query_out_of_context",
  "do not mention",
  "does not mention",
  "don't mention",
  "not mentioned in",
  "not referenced in",
  "is not referenced",
  "not in the provided",
  "not in my documents",
  "not in your documents",
  "not found in the provided",
  "no mention of",
  "don't have enough information",
  "do not have enough information",
  "not have enough information",
  "cannot provide an answer",
  "can't provide an answer",
  "unable to provide an answer",
  "cannot answer based on",
  "can't answer based on",
  "unable to answer based on",
  "no relevant information",
  "information is not available",
  "keine antwort geben",
  "auf der grundlage der verfügbaren informationen keine",
  "nicht genug informationen",
  "nicht über genügend informationen",
  "llm failed to respond",
  "i cannot share sensitive personal or financial details from uploaded documents",
] as const;

export function shouldHideChatCitations(answer: string | undefined | null): boolean {
  const text = (answer ?? "").toLowerCase().trim();
  if (!text) return true;
  return CHAT_CITATION_SUPPRESSION_PHRASES.some((phrase) => text.includes(phrase));
}
