import React, { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';
import { useAuth } from '@/hooks/useAuth';
import { User, AuthState } from '@/services/api/api';
import { useToast } from '@/hooks/useToast';
import { useQueryClient } from '@tanstack/react-query';

interface AuthContextType {
  isAuthenticated: boolean;
  user: User | null;
  token: string | null;
  /** True during bootstrap, logout, or 2FA verify — not tied to background token verify */
  isLoading: boolean;
  /** True only while login HTTP request is in flight (use for login form, not full-shell loading) */
  isLoggingIn: boolean;
  error: string | null;

  requires2FA: boolean;
  temp2FAToken: string | null;
  isVerifying2FA: boolean;
  verify2FAError: Error | null;

  login: (credentials: { username: string; password: string }) => void;
  logout: () => void;
  clearError: () => void;
  verifyLogin2FA: (code: string) => void;
  resendLogin2FA: () => void;
  isResendingLogin2FA: boolean;
  clear2FA: () => void;
}

const defaultAuthContextValue: AuthContextType = {
  isAuthenticated: false,
  user: null,
  token: null,
  isLoading: true,
  isLoggingIn: false,
  error: null,
  requires2FA: false,
  temp2FAToken: null,
  isVerifying2FA: false,
  verify2FAError: null,
  login: () => {
    console.warn('login called before AuthProvider is initialized');
  },
  logout: () => {
    console.warn('logout called before AuthProvider is initialized');
  },
  clearError: () => {
    console.warn('clearError called before AuthProvider is initialized');
  },
  verifyLogin2FA: () => {
    console.warn('verifyLogin2FA called before AuthProvider is initialized');
  },
  resendLogin2FA: () => {
    console.warn('resendLogin2FA called before AuthProvider is initialized');
  },
  isResendingLogin2FA: false,
  clear2FA: () => {
    console.warn('clear2FA called before AuthProvider is initialized');
  },
};

export const AuthContext = createContext<AuthContextType>(defaultAuthContextValue);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const {
    login: loginMutation,
    logout: logoutMutation,
    isLoggingIn,
    isLoggingOut,
    loginError,
    logoutError,
    isAuthenticated,
    user,
    token,
    resetLogin,
    requires2FA,
    temp2FAToken,
    verifyLogin2FA,
    isVerifying2FA,
    verify2FAError,
    resendLogin2FA,
    isResendingLogin2FA,
    clear2FA,
  } = useAuth();

  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [error, setError] = useState<string | null>(null);
  const [isInitializing, setIsInitializing] = useState<boolean>(true);

  // Short bootstrap only — do not tie this to token verify (verify runs in background).
  useEffect(() => {
    const initTimer = setTimeout(() => {
      setIsInitializing(false);
    }, 100);
    return () => clearTimeout(initTimer);
  }, []);

  useEffect(() => {
    const handleSessionExpired = (event: CustomEvent) => {
      const errorMessage = event.detail?.message || 'Session expired due to inactivity';
      
      toast({
        title: 'Session Expired',
        description: errorMessage,
        variant: 'destructive',
      });

      queryClient.clear();
      window.dispatchEvent(new CustomEvent('auth-token-updated'));
    };

    window.addEventListener('session-expired', handleSessionExpired as EventListener);

    return () => {
      window.removeEventListener('session-expired', handleSessionExpired as EventListener);
    };
  }, [toast, queryClient]);

  useEffect(() => {
    if (verify2FAError) {
      let errorMessage = '2FA verification failed. Please try again.';
      
      if (verify2FAError instanceof Error) {
        const axiosError = verify2FAError as any;
        const errorData = axiosError.response?.data;
        const errorDetail = errorData?.detail || '';

        if (errorDetail) {
          errorMessage = errorDetail;
        } else if (axiosError.response?.status === 401) {
          if (errorDetail.includes('expired') || errorDetail.includes('temporary token')) {
            errorMessage = 'The login session has expired. Please log in again.';
          } else if (errorDetail.includes('Invalid 2FA code') || errorDetail.includes('TOTP')) {
            errorMessage = 'Invalid 2FA code. Please check your authenticator app and try again.';
          } else {
            errorMessage = 'Authentication failed. Please try again.';
          }
        } else if (axiosError.message && !axiosError.message.includes('status code')) {
          errorMessage = axiosError.message;
        }
      }
      
      setError(errorMessage);
    }
  }, [verify2FAError]);

  useEffect(() => {
    if (loginError) {
      let errorMessage = 'Login failed. Please check your credentials.';

      if (loginError instanceof Error) {
        const axiosError = loginError as any;
        const hasResponse = !!axiosError.response;

        // No HTTP response: network, proxy refused, DNS, CORS, etc.
        if (!hasResponse) {
          const code = axiosError.code as string | undefined;
          const msg = String(axiosError.message || '').toLowerCase();
          if (code === 'ECONNABORTED' || msg.includes('timeout')) {
            errorMessage =
              'The request took too long. Please try again in a moment.';
          } else if (
            code === 'ECONNREFUSED' ||
            code === 'ERR_NETWORK' ||
            msg.includes('network error') ||
            msg.includes('econnrefused')
          ) {
            errorMessage =
              'We couldn\'t connect to the server. Please check your internet connection and try again.';
          } else if (axiosError.message && !axiosError.message.includes('status code')) {
            errorMessage = axiosError.message;
          }
        } else if (axiosError.response?.data) {
          const responseData = axiosError.response.data;

          if (responseData.detail) {
            errorMessage = typeof responseData.detail === 'string'
              ? responseData.detail
              : JSON.stringify(responseData.detail);
          }
          else if (responseData.message) {
            errorMessage = responseData.message;
          }
          else if (responseData.error) {
            errorMessage = responseData.error;
          }
        }

        if (hasResponse && axiosError.response?.status === 401) {
          errorMessage = 'Invalid username or password. Please try again.';
        } else if (hasResponse && axiosError.response?.status === 429) {
          errorMessage = 'Too many login attempts. Please wait a few minutes and try again.';
        } else if (hasResponse && axiosError.response?.status === 403) {
          const errCode = axiosError.response?.headers?.['x-error-code'];
          if (errCode === 'EMAIL_NOT_VERIFIED' && axiosError.response?.data?.detail) {
            errorMessage = typeof axiosError.response.data.detail === 'string'
              ? axiosError.response.data.detail
              : 'Email verification required. Please check your inbox.';
          } else {
            errorMessage = 'Access denied. Please contact your administrator.';
          }
        } else if (hasResponse && axiosError.response?.status === 404) {
          errorMessage = 'Login endpoint not found. Please contact support.';
        } else if (hasResponse && axiosError.response?.status >= 500) {
          errorMessage = 'Server error. Please try again later.';
        } else if (hasResponse && axiosError.response?.status === 400) {
          errorMessage = 'Invalid request. Please check your input.';
        }
      }

      setError(errorMessage);
    } else if (logoutError) {
      let errorMessage = 'Logout failed.';
      
      if (logoutError instanceof Error) {
        const axiosError = logoutError as any;
        if (axiosError.response?.data?.detail) {
          errorMessage = axiosError.response.data.detail;
        } else if (axiosError.response?.data?.message) {
          errorMessage = axiosError.response.data.message;
        } else if (axiosError.message && !axiosError.message.includes('status code')) {
          errorMessage = axiosError.message;
        }
      }
      
      setError(errorMessage);
    } else {
      setError(null);
    }
  }, [loginError, logoutError]);

  const isWidgetMode = typeof window !== 'undefined' && !!(window as any).RAGSUITE_PROJECT_ID;
  const projectId = isWidgetMode ? (window as any).RAGSUITE_PROJECT_ID : null;

  useEffect(() => {
    void isWidgetMode;
    void projectId;
  }, [isAuthenticated, user, token, isInitializing, isLoggingIn, isLoggingOut, error, isWidgetMode, projectId]);

  const clearError = useCallback(() => {
    setError(null);
    resetLogin();
  }, [resetLogin]);

  const login = useCallback((credentials: { username: string; password: string }) => {
    setError(null);
    loginMutation(credentials);
  }, [loginMutation]);

  const logout = useCallback(() => {
    setError(null);
    logoutMutation();
  }, [logoutMutation]);

  const value = useMemo<AuthContextType>(() => ({
    isAuthenticated,
    user,
    token,
    isLoading: isInitializing || isLoggingIn || isLoggingOut || isVerifying2FA,
    isLoggingIn,
    error,

    requires2FA,
    temp2FAToken,
    isVerifying2FA,
    verify2FAError,

    login,
    logout,
    clearError,
    verifyLogin2FA,
    resendLogin2FA,
    isResendingLogin2FA,
    clear2FA,
  }), [
    isAuthenticated,
    user,
    token,
    isInitializing,
    isLoggingIn,
    isLoggingOut,
    error,
    requires2FA,
    temp2FAToken,
    isVerifying2FA,
    verify2FAError,
    login,
    logout,
    clearError,
    verifyLogin2FA,
    resendLogin2FA,
    isResendingLogin2FA,
    clear2FA,
  ]);

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuthContext() {
  const context = useContext(AuthContext);
  return context;
}

export function useAuthGuard() {
  const { isAuthenticated, isLoading } = useAuthContext();

  return {
    isAuthenticated,
    isLoading,
    shouldRedirect: !isAuthenticated && !isLoading,
  };
}
