import { onboardingAPI } from "@/services/api/api";
import { ROUTES } from "@/constants/routes";
import { APP_STORAGE_KEYS } from "@/constants/app";

export const FORCE_ONBOARDING_SESSION_KEY = "force_onboarding";

/** Align with backend JWT default (60 minutes). */
export const AUTH_SESSION_TTL_MS = 60 * 60 * 1000;

export interface PersistAuthUser {
  id: number | string;
  username: string;
  email: string;
  is_admin?: boolean;
  created_at?: string;
  last_login?: string | null;
}

export interface PersistAuthPayload {
  access_token: string;
  user: PersistAuthUser;
}

function isExpiryStillValid(expiresAt: string): boolean {
  const expirationDate = new Date(expiresAt);
  if (Number.isNaN(expirationDate.getTime())) return false;

  const now = Date.now();
  const timeDiffMinutes = Math.round((expirationDate.getTime() - now) / (1000 * 60));
  const isLikelyTimezoneIssue = timeDiffMinutes < 0 && timeDiffMinutes > -360;
  if (isLikelyTimezoneIssue) return true;

  return expirationDate.getTime() > now;
}

export function writeAuthTokenExpires(ttlMs: number = AUTH_SESSION_TTL_MS): void {
  localStorage.setItem(
    APP_STORAGE_KEYS.TOKEN_EXPIRES,
    new Date(Date.now() + ttlMs).toISOString(),
  );
}

export function clearStoredAuthSession(): void {
  localStorage.removeItem(APP_STORAGE_KEYS.USER_DATA);
  localStorage.removeItem(APP_STORAGE_KEYS.TOKEN_EXPIRES);
  localStorage.removeItem("auth-user");
  localStorage.removeItem("temp_2fa_token");
  window.dispatchEvent(new CustomEvent("auth-token-updated"));
}

export function hasStoredAuthSession(): boolean {
  const userData = localStorage.getItem(APP_STORAGE_KEYS.USER_DATA);
  const expiresAt = localStorage.getItem(APP_STORAGE_KEYS.TOKEN_EXPIRES);

  if (!userData || userData === "null" || userData === "undefined") return false;
  if (!expiresAt || expiresAt === "null" || expiresAt === "undefined") return false;

  return isExpiryStillValid(expiresAt);
}

export function persistAuthSession(payload: PersistAuthPayload): void {
  const { user } = payload;
  const userData = {
    id: String(user.id),
    username: user.username,
    email: user.email,
    role: user.is_admin ? "admin" : "user",
    permissions: user.is_admin ? ["read", "write", "admin"] : ["read", "write"],
    createdAt: user.created_at || new Date().toISOString(),
    lastLogin: user.last_login || undefined,
  };

  localStorage.setItem(APP_STORAGE_KEYS.USER_DATA, JSON.stringify(userData));
  writeAuthTokenExpires();

  window.dispatchEvent(new CustomEvent("auth-token-updated"));
}

export async function resolvePostAuthPath(): Promise<string> {
  if (!hasStoredAuthSession()) {
    return ROUTES.LOGIN;
  }
  try {
    const status = await onboardingAPI.getStatus();
    if (status?.redirect_to) {
      return status.redirect_to;
    }
    if (status?.needs_onboarding) {
      return ROUTES.ONBOARDING;
    }
  } catch {
    /* fall through */
  }
  const completed = localStorage.getItem(APP_STORAGE_KEYS.ONBOARDING_COMPLETED);
  if (completed === "true") {
    return ROUTES.OVERVIEW;
  }
  return ROUTES.ONBOARDING;
}

export function navigateToPostAuthPath(path: string): void {
  let target = path;
  if (target === ROUTES.LOGIN && hasStoredAuthSession()) {
    target = ROUTES.OVERVIEW;
  }

  const current = window.location.pathname;
  if (target === current) {
    return;
  }

  if (target === ROUTES.ONBOARDING) {
    sessionStorage.setItem(FORCE_ONBOARDING_SESSION_KEY, "1");
  }
  window.location.assign(target);
}

export function markOnboardingCompleted(): void {
  localStorage.setItem(APP_STORAGE_KEYS.ONBOARDING_COMPLETED, "true");
  sessionStorage.removeItem(FORCE_ONBOARDING_SESSION_KEY);
}
