export const crawlAPI = {
  normalizeUrl(input: string) {
    if (!input) return '';
    const trimmed = (input || '').toString().trim();
    const unquoted = trimmed.replace(/^([`"'])(.*)\1$/, '$2');
    const collapsed = unquoted.replace(/\s+/g, ' ');
    return collapsed;
  },
  addSite: async (siteData: CrawlSiteData) => {
    try {
      if (!siteData.name || !siteData.url) {
        throw new Error('Name and URL are required');
      }

      const backendData = {
        name: siteData.name,
        base_url: crawlAPI.normalizeUrl(siteData.url),
        description: siteData.description || '',
        depth: siteData.crawlDepth ?? 2,
        cadence: siteData.cadence || 'ONCE',
        headless_mode: siteData.headlessMode || 'AUTO',
        allowlist: Array.isArray(siteData.includePatterns) ? siteData.includePatterns : [],
        denylist: Array.isArray(siteData.excludePatterns) ? siteData.excludePatterns : [],
        skip_header_footer: siteData.skipHeaderFooter ?? true,
      };

      const response = await apiClient.post('/crawl/sites', backendData);

      if (!response || !response.data) {
        console.warn('⚠️ API returned invalid response, returning success object');
        return {
          id: `temp-${Date.now()}`,
          ...backendData
        };
      }

      return response.data;
    } catch (error) {
      console.error('❌ Add site failed:', error);

      if ((error as any).response?.status === 401) {
        console.error('🔐 Authentication failed - please log in again');
        localStorage.removeItem('auth-user');
        localStorage.removeItem('user_data');
        localStorage.removeItem('token_expires');
        window.location.href = '/login';
        throw new Error('Authentication failed. Please log in again.');
      }

      if ((error as any).response?.status === 403) {
        console.error('🔐 Access forbidden - insufficient permissions');
        throw new Error('Access forbidden. Please check your permissions.');
      }

      const errorMessage = (error as any).response?.data?.detail ||
        (error as any).message ||
        'Failed to add site. Please try again.';
      throw new Error(errorMessage);
    }
  },

  getSites: async () => {

    const response = await apiClient.get('/crawl/sites');
    const raw = response.data;

    let list: any[] = [];

    if (Array.isArray(raw)) {
      list = raw;
    } else if (raw && typeof raw === "object" && Array.isArray(raw.data)) {
      list = raw.data;
    } else {
      list = [];
    }

    return list.map((site: any) => {
      const pipelineStatus = site.pipeline_status ?? undefined;
      const activeJobId = site.active_job_id ?? undefined;

      return {
      id: site.id ?? "",
      name: site.name ?? "",
      url: crawlAPI.normalizeUrl(site.base_url ?? ""),
      description: site.description ?? "",
      status: mapPipelineToSiteStatus(pipelineStatus, site.status) as
        "active" | "inactive" | "crawling" | "indexing" | "error",
      lastCrawled: site.last_crawl_at ?? null,
      pagesCrawled: site.documents_count ?? 0,
      progress: site.progress_percentage ?? site.progress ?? undefined,
      activeJobId,
      currentJobId: activeJobId,
      latestJobId: site.latest_job_id ?? undefined,
      createdAt: site.created_at ?? new Date().toISOString(),
      updatedAt: site.updated_at ?? new Date().toISOString(),
      crawlDepth: site.depth ?? 2,
      cadence: site.cadence ?? "ONCE",
      headlessMode: site.headless_mode ?? "AUTO",
      includePatterns: site.allowlist ?? [],
      excludePatterns: site.denylist ?? [],
      skipHeaderFooter: site.skip_header_footer ?? true,
      trainedAt: site.trained_at ?? null,
      isTrained: !!site.trained_at,
      pipelineStatus,
      isSearchReady: !!site.is_search_ready,
    };
    });
  },

  updateSite: async (id: string, siteData: CrawlSiteData) => {
    try {
      const backendData = {
        name: siteData.name,
        base_url: crawlAPI.normalizeUrl(siteData.url),
        description: siteData.description || '',
        depth: siteData.crawlDepth ?? 2,
        cadence: siteData.cadence || 'ONCE',
        headless_mode: siteData.headlessMode || 'AUTO',
        allowlist: Array.isArray(siteData.includePatterns) ? siteData.includePatterns : [],
        denylist: Array.isArray(siteData.excludePatterns) ? siteData.excludePatterns : [],
        skip_header_footer: siteData.skipHeaderFooter ?? true,
      };

      const response = await apiClient.put(`/crawl/sites/${id}`, backendData);
      return response.data;
    } catch (error) {
      console.error('❌ Update site failed:', error);
      throw error;
    }
  },

  deleteSite: async (id: string) => {
    try {
      const response = await apiClient.delete(`/crawl/sites/${id}`);
      return response.data;
    } catch (error) {
      console.error('❌ Delete site failed:', error);
      throw error;
    }
  },

  startCrawl: async (id: string) => {
    try {
      const response = await apiClient.post(`/crawl/start/${id}`);
      return response.data;
    } catch (error) {
      console.error('❌ Start crawl failed:', error);
      throw error;
    }
  },

  getCrawlStatus: async (id: string) => {
    try {
      const response = await apiClient.get(`/crawl/status/${id}`);
      const d = response.data;
      return {
        id: d.job_id,
        status: d.status === 'PENDING' ? 'pending' :
          d.status === 'RUNNING' ? 'running' :
            d.status === 'COMPLETED' ? 'completed' :
              d.status === 'FAILED' ? 'failed' : 'cancelled',
        progress: d.progress_percentage || 0,
        pagesFound: d.pages_fetched || 0,
        pagesCrawled: d.pages_fetched || 0,
        startedAt: d.started_at || d.queued_at,
        completedAt: d.finished_at,
        error: d.errors?.[0] || null,
        logs: d.errors || [],
        // URL detail lists
        crawledUrls: (d.crawled_urls || []) as Array<{ url: string }>,
        crawledUrlsTotal: (d.crawled_urls_total ?? d.pages_fetched ?? 0) as number,
        skippedUrls: (d.skipped_urls || []) as Array<{ url: string; reason: string }>,
        skippedCount: (d.skipped_count ?? 0) as number,
        failedUrls: (d.failed_urls || []) as Array<{ url: string; reason: string; status_code?: number }>,
        failedCount: (d.failed_count ?? 0) as number,
        isTrained: !!d.is_trained,
        trainedAt: d.trained_at ?? null,
        pipelineStatus: d.pipeline_status ?? undefined,
        isSearchReady: !!d.is_search_ready,
      };
    } catch (error) {
      console.error('❌ Get crawl status failed:', error);
      throw error;
    }
  },

  previewUrl: async (url: string) => {
    try {
      const response = await apiClient.put('/crawl/preview', { url });
      return {
        url: response.data.url,
        title: response.data.meta?.title || 'No Title',
        content: response.data.html_sample || '',
        text: response.data.text_sample || '',
        links: [],
        images: [],
        metadata: response.data.meta || {},
        status: response.data.meta?.status_code || 200,
        responseTime: 0
      };
    } catch (error) {
      console.error('❌ Preview URL failed:', error);
      throw error;
    }
  },

};

export const compareAPI = {
  compareSearch: async (payload: CompareSearchRequest): Promise<CompareSearchResponse> => {
    try {
      const response = await apiClient.post<CompareSearchResponse>('/search/compare', payload);
      return response.data;
    } catch (error) {
      console.error('❌ Compare search failed:', error);
      throw error;
    }
  },

  compareSearchStream: async (
    payload: CompareSearchRequest,
    handlers: {
      onStarted?: (data: { query: string; total_models: number }) => void;
      onModelResult?: (data: { completed: number; total_models: number; result: any }) => void;
      onCompleted?: (data: CompareSearchResponse) => void;
    }
  ): Promise<void> => {
    const projectId = getWidgetProjectId();
    const isWidgetMode = !!projectId;
    const runtimeApiBase =
      typeof window !== "undefined" && (window as any).RAGSUITE_API_URL
        ? String((window as any).RAGSUITE_API_URL).replace(/\/$/, "")
        : String(API_BASE_URL).replace(/\/$/, "");
    const url = `${runtimeApiBase}/search/compare/stream${isWidgetMode ? `?project_id=${encodeURIComponent(projectId!)}` : ''}`;

    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
      Accept: 'text/event-stream',
    };
    if (isWidgetMode && projectId) headers['X-Project-ID'] = projectId;

    const response = await fetch(url, {
      method: 'POST',
      headers,
      body: JSON.stringify(payload),
      credentials: 'include',
    });

    if (!response.ok || !response.body) {
      throw new Error(`Stream request failed (${response.status})`);
    }

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';
    let eventName = '';

    const processMessage = (chunk: string) => {
      const lines = chunk.split('\n');
      let dataLine = '';
      for (const line of lines) {
        if (line.startsWith('event:')) eventName = line.slice(6).trim();
        if (line.startsWith('data:')) dataLine += line.slice(5).trim();
      }
      if (!dataLine) return;
      const payloadData = JSON.parse(dataLine);
      if (eventName === 'compare_started') handlers.onStarted?.(payloadData);
      if (eventName === 'model_result') handlers.onModelResult?.(payloadData);
      if (eventName === 'compare_completed') handlers.onCompleted?.(payloadData);
    };

    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      const messages = buffer.split('\n\n');
      buffer = messages.pop() || '';
      for (const msg of messages) {
        if (msg.trim()) processMessage(msg);
      }
    }
  },

  getModelProfiles: async (): Promise<ModelProfilesListResponse> => {
    try {
      const response = await apiClient.get<{
        success: boolean;
        data: ModelProfilesListResponse | ModelConfigProfile[];
      }>('/search/models/profiles/');
      const data = response.data.data;
      if (Array.isArray(data)) {
        return { configured_source: 'search', effective_source: 'search', profiles: data };
      }
      return {
        configured_source: data?.configured_source ?? 'search',
        effective_source: data?.effective_source ?? 'search',
        profiles: data?.profiles ?? [],
      };
    } catch (error) {
      console.error('❌ Get model profiles failed:', error);
      throw error;
    }
  },

  createModelProfile: async (data: {
    provider: string;
    model_name: string;
    api_key?: string;
    compare_enabled?: boolean;
    extra_params?: Record<string, unknown>;
    profile_type?: string;
  }): Promise<ModelConfigProfile> => {
    try {
      const response = await apiClient.post('/search/models/profiles/', data);
      return response.data.data;
    } catch (error) {
      console.error('❌ Create model profile failed:', error);
      throw error;
    }
  },

  updateModelProfile: async (profileId: string, updates: { compare_enabled?: boolean }): Promise<void> => {
    try {
      await apiClient.put(`/search/models/profiles/${profileId}`, updates);
    } catch (error) {
      console.error('❌ Update model profile failed:', error);
      throw error;
    }
  },

  deleteModelProfile: async (profileId: string): Promise<void> => {
    try {
      await apiClient.delete(`/search/models/profiles/${profileId}`);
    } catch (error) {
      console.error('❌ Delete model profile failed:', error);
      throw error;
    }
  },
};
