export const DEFAULT_WIDGET_BACKGROUND = "#1a1a1a";
export const DEFAULT_WIDGET_TEXT_COLOR = "#ffffff";
export const DEFAULT_WIDGET_WIDTH = 448;
export const MIN_WIDGET_WIDTH = 320;
export const MAX_WIDGET_WIDTH = 900;

type Rgb = { r: number; g: number; b: number };

function parseHexColor(color: string): Rgb | null {
  const hex = color.trim();
  if (!hex.startsWith("#")) return null;

  let value = hex.slice(1);
  if (value.length === 3) {
    value = value.split("").map((char) => char + char).join("");
  }
  if (value.length !== 6) return null;

  const r = Number.parseInt(value.slice(0, 2), 16);
  const g = Number.parseInt(value.slice(2, 4), 16);
  const b = Number.parseInt(value.slice(4, 6), 16);
  if ([r, g, b].some((channel) => Number.isNaN(channel))) return null;

  return { r, g, b };
}

function toHex({ r, g, b }: Rgb): string {
  const channel = (value: number) => Math.max(0, Math.min(255, Math.round(value))).toString(16).padStart(2, "0");
  return `#${channel(r)}${channel(g)}${channel(b)}`;
}

function mixColors(colorA: string, colorB: string, ratio: number): string {
  const a = parseHexColor(colorA);
  const b = parseHexColor(colorB);
  if (!a || !b) return colorA;

  const weight = Math.max(0, Math.min(1, ratio));
  return toHex({
    r: a.r + (b.r - a.r) * weight,
    g: a.g + (b.g - a.g) * weight,
    b: a.b + (b.b - a.b) * weight,
  });
}

export function getRelativeLuminance(color: string): number {
  const rgb = parseHexColor(color);
  if (!rgb) return 0;

  const normalize = (channel: number) => {
    const value = channel / 255;
    return value <= 0.03928 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4;
  };

  const r = normalize(rgb.r);
  const g = normalize(rgb.g);
  const b = normalize(rgb.b);
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

export function isLightBackground(color: string): boolean {
  return getRelativeLuminance(color) > 0.5;
}

export function suggestTextColorForBackground(background: string): string {
  return isLightBackground(background) ? "#1a1a1a" : "#ffffff";
}

export function getWidgetThemeStyleVars(
  background = DEFAULT_WIDGET_BACKGROUND,
  textColor = DEFAULT_WIDGET_TEXT_COLOR,
): Record<string, string> {
  const bg = parseHexColor(background) ? background : DEFAULT_WIDGET_BACKGROUND;
  const text = parseHexColor(textColor) ? textColor : DEFAULT_WIDGET_TEXT_COLOR;

  return {
    "--chatbot-background": bg,
    "--chatbot-text-color": text,
    "--chatbot-surface": mixColors(bg, text, 0.12),
    "--chatbot-border-color": mixColors(bg, text, 0.28),
    "--chatbot-muted-text": mixColors(text, bg, 0.45),
    "--chatbot-input-background": mixColors(bg, text, 0.06),
  };
}
