import axios from 'axios';
import { isPublicAuthPath } from '@/constants/routes';

const getApiBaseUrl = () => {
  if (import.meta.env.VITE_API_BASE_URL) {
    return import.meta.env.VITE_API_BASE_URL;
  }
  if (typeof window !== 'undefined' && (window as any).RAGSUITE_API_URL) {
    return (window as any).RAGSUITE_API_URL;
  }
  // Dev: same-origin path so Vite can proxy to the API (see vite.config.ts). Production builds must set VITE_API_BASE_URL.
  if (import.meta.env.DEV) {
    return '/api/v1';
  }
  // Production fallback: keep same-origin to avoid hardcoded LAN hosts.
  return '/api/v1';
};

export const API_BASE_URL = getApiBaseUrl();

/** LAN-style hosts Google rejects for Web OAuth redirect URIs when consent runs in a normal browser. */
function isLikelyBlockedOAuthRedirectHost(hostname: string): boolean {
  const h = hostname.toLowerCase();
  if (!h || h === 'localhost' || h === '127.0.0.1') return false;
  if (/^192\.168\.\d+\.\d+$/.test(h)) return true;
  if (/^10\.\d+\.\d+\.\d+$/.test(h)) return true;
  if (/^172\.(1[6-9]|2\d|3[01])\.\d+\.\d+$/.test(h)) return true;
  return false;
}

/** Gmail OAuth redirect — must match backend route and Google Console "Authorized redirect URIs". */
export function getGmailOAuthRedirectUri(): string {
  let base = API_BASE_URL.replace(/\/$/, '');
  if (typeof window !== 'undefined' && (window as any).RAGSUITE_API_URL) {
    base = String((window as any).RAGSUITE_API_URL).replace(/\/$/, '');
  }
  if (base.startsWith('/')) {
    base = `${typeof window !== 'undefined' ? window.location.origin : ''}${base}`;
  }

  // If you open the UI via localhost but VITE_API_BASE_URL points at a LAN IP, Google OAuth will fail.
  // Prefer same-origin /api/v1 (Vite proxy to backend) so redirect stays on localhost.
  if (typeof window !== 'undefined') {
    try {
      const parsed = new URL(base);
      const ui = window.location.hostname.toLowerCase();
      const uiLoopback = ui === 'localhost' || ui === '127.0.0.1';
      if (uiLoopback && isLikelyBlockedOAuthRedirectHost(parsed.hostname)) {
        base = `${window.location.origin}/api/v1`;
      }
    } catch {
      /* ignore */
    }
  }

  return `${base.replace(/\/$/, '')}/gmail/auth/callback`;
}

function fixTruncatedGmailCallbackPath(uri: string): string {
  const trimmed = uri.trim();
  const noTrail = trimmed.replace(/\/+$/, '');
  if (noTrail.endsWith('/gmail/auth/callback')) return trimmed;
  if (/\/gmail\/auth$/.test(noTrail)) return `${noTrail}/callback`;
  return trimmed;
}

/**
 * Normalize a redirect URI loaded from the API (fixes missing `/callback`, LAN IP while UI is on localhost).
 */
export function coerceSavedGmailRedirectUri(saved?: string | null): string {
  const detected = getGmailOAuthRedirectUri();
  if (!saved?.trim()) return detected;
  let u = fixTruncatedGmailCallbackPath(saved);
  if (typeof window !== 'undefined') {
    try {
      const parsed = new URL(u);
      const ui = window.location.hostname.toLowerCase();
      const uiLoopback = ui === 'localhost' || ui === '127.0.0.1';
      if (uiLoopback && isLikelyBlockedOAuthRedirectHost(parsed.hostname)) {
        return detected;
      }
    } catch {
      return detected;
    }
  }
  return u;
}

export const getWidgetProjectId = (): string | null => {
  if (typeof window === 'undefined') return null;

  const getSearchWidgetProjectId = (window as any).__RAGSUITE_GET_SEARCH_WIDGET_PROJECT_ID__;
  if (typeof getSearchWidgetProjectId === 'function') {
    const instanceId = getSearchWidgetProjectId();
    if (instanceId) return instanceId;
  }

  return (window as any).RAGSUITE_PROJECT_ID || null;
};

export const apiClient = axios.create({
  baseURL: API_BASE_URL,
  timeout: 3000000,
  withCredentials: true,
  headers: {
    'Content-Type': 'application/json',
  },
});

apiClient.interceptors.request.use(
  (config) => {
    if (typeof window !== 'undefined' && (window as any).RAGSUITE_API_URL) {
      config.baseURL = (window as any).RAGSUITE_API_URL;
    }

    const projectId = getWidgetProjectId();
    const isWidgetMode = !!projectId;

    if (isWidgetMode) {
      config.headers['X-Project-ID'] = projectId;
      config.headers['X-Widget-Mode'] = 'true';
      if (!config.params) {
        config.params = {};
      }
      config.params.project_id = projectId;

      let currentDomain = (window as any).RAGSUITE_CURRENT_DOMAIN;

      if (!currentDomain && window.location && window.location.hostname) {
        currentDomain = window.location.hostname.split(':')[0];
        (window as any).RAGSUITE_CURRENT_DOMAIN = currentDomain;
      }

      if (currentDomain) {
        config.headers['X-Request-Domain'] = currentDomain;
      } else {
        console.error('❌ RAG Suite Widget: Could not extract domain for validation!', {
          hostname: window.location?.hostname,
          RAGSUITE_CURRENT_DOMAIN: (window as any).RAGSUITE_CURRENT_DOMAIN,
          RAGSUITE_PROJECT_ID: projectId
        });
      }

      const currentUrl = window.location?.href;
      if (currentUrl) {
        config.headers['X-Request-Url'] = currentUrl;
      }
    }

    return config;
  },
  (error) => {
    console.error('❌ Request Error:', error);
    return Promise.reject(error);
  }
);

apiClient.interceptors.response.use(
  (response) => {
    return response;
  },
  (error) => {
    const isCORBError = error.message?.includes('CORB') || error.message?.includes('Cross-Origin');
    const isCORSError = error.code === 'ERR_NETWORK' || error.message?.includes('CORS') || error.message?.includes('blocked');

    if (isCORBError || isCORSError) {
      if (typeof window !== 'undefined') {
        (window as any).__HAS_CORB_CORS_ERROR = true;
      }
      if (!(window as any).__CORB_ERROR_LOGGED) {
        console.warn('⚠️ CORB/CORS Error: Cross-origin requests are being blocked. Please configure CORS headers on the backend server.');
        (window as any).__CORB_ERROR_LOGGED = true;
      }
      return Promise.reject(error);
    }

    if (import.meta.env.DEV || (error.response?.status && error.response.status >= 500)) {
      console.error('❌ API Error:', {
        message: error.message,
        code: error.code,
        status: error.response?.status,
        url: error.config?.url,
      });
    }

    if (error.code === 'ERR_NETWORK' && !isCORBError) {
      if (!(window as any).__NETWORK_ERROR_LOGGED) {
        console.error('🌐 Network Error: Cannot reach the server. Check if the API server is running at:', API_BASE_URL);
        (window as any).__NETWORK_ERROR_LOGGED = true;
      }
    }

    if (error.response?.status === 401) {
      const isWidgetMode = typeof window !== 'undefined' && !!getWidgetProjectId();
      const isActivationEndpoint = error.config?.url?.includes('/activate') || error.config?.url?.includes('/activation');

      if (isWidgetMode && isActivationEndpoint) {
        return Promise.reject(error);
      }

      const isLoginRequest = error.config?.url?.includes('/login') || error.config?.url?.includes('/auth/login');

      if (isLoginRequest) {
        console.warn('🔐 Login failed - invalid credentials');
        return Promise.reject(error);
      }

      const is2FARequest = error.config?.url?.includes('/2fa/verify') ||
        error.config?.url?.includes('/2fa/disable') ||
        error.config?.url?.includes('/user/2fa/verify') ||
        error.config?.url?.includes('/user/2fa/disable');

      if (is2FARequest) {
        console.warn('🔐 2FA verification/disable failed - error will be handled by component');
        return Promise.reject(error);
      }

      const errorDetail = error.response?.data?.detail || '';
      const errorDetailLower = typeof errorDetail === 'string' ? errorDetail.toLowerCase() : '';

      const isInactivityTimeout = errorDetailLower.includes('session expired due to inactivity');
      const isSessionRevoked = errorDetailLower.includes('session has been revoked') ||
        errorDetailLower.includes('session revoked');
      const isSessionExpired = errorDetailLower.includes('session expired') &&
        !errorDetailLower.includes('inactivity');

      if ((isInactivityTimeout || isSessionRevoked || isSessionExpired) && !isWidgetMode) {
        const logMessage = isSessionRevoked
          ? '🔐 Session has been revoked - logging out automatically'
          : isInactivityTimeout
            ? '🔐 Session expired due to inactivity - logging out automatically'
            : '🔐 Session expired - logging out automatically';

        console.warn(logMessage);

        (error as any).__isSessionError = true;
        (error as any).__isHandled = true;

        localStorage.removeItem('auth-user');
        localStorage.removeItem('user_data');
        localStorage.removeItem('token_expires');

        if (typeof window !== 'undefined') {
          window.dispatchEvent(new CustomEvent('session-expired', {
            detail: { message: errorDetail }
          }));
        }

        if (
          typeof window !== 'undefined' &&
          !isPublicAuthPath(window.location.pathname)
        ) {
          setTimeout(() => {
            window.location.href = '/login';
          }, 50);
        }

        return Promise.reject(error);
      }

      if (!isWidgetMode) {
        console.warn('🔐 Authentication failed (401) - logging out');

        (error as any).__isSessionError = true;
        (error as any).__isHandled = true;

        localStorage.removeItem('auth-user');
        localStorage.removeItem('user_data');
        localStorage.removeItem('token_expires');

        if (
          typeof window !== 'undefined' &&
          !isPublicAuthPath(window.location.pathname)
        ) {
          setTimeout(() => {
            window.location.href = '/login';
          }, 50);
        }
      } else {
        if (import.meta.env.DEV) {
          console.warn('🔐 Authentication failed (401) - request rejected');
        }
      }
    }

    return Promise.reject(error);
  }
);
