import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { chatAPI, ChatResponse, ChatSession } from '@/services/api/api';
import { invalidateFeedbackModeration } from '@/services/api/feedbackModeration';

export const useChat = () => {
  const queryClient = useQueryClient();

  const sendMessageMutation = useMutation({
    mutationFn: ({ message, sessionId, ragSettings }: {
      message: string;
      sessionId?: string;
      ragSettings?: {
        topK?: number;
        similarityThreshold?: number;
        useReranker?: boolean;
        maxTokens?: number;
      };
    }) =>
      chatAPI.sendMessage(message, sessionId, ragSettings),

    onSuccess: (data: ChatResponse) => {
      queryClient.invalidateQueries({ queryKey: ['chat-sessions'] });
    },

    onError: (error) => {
      console.error('❌ Chat message failed:', error);
    },
  });

  return {
    sendMessage: sendMessageMutation.mutate,
    sendMessageAsync: sendMessageMutation.mutateAsync,
    isSending: sendMessageMutation.isPending,
    chatData: sendMessageMutation.data,
    chatError: sendMessageMutation.error,
  };
};

export const useChatSessions = () => {
  const sessionsQuery = useQuery({
    queryKey: ['chat-sessions'],
    queryFn: chatAPI.getSessions,
    staleTime: 30000,
  });

  const deleteSessionMutation = useMutation({
    mutationFn: (sessionId: string) => chatAPI.deleteSession(sessionId),

    onSuccess: () => {
      sessionsQuery.refetch();
    },

    onError: (error) => {
      console.error('❌ Delete session failed:', error);
    },
  });

  return {
    sessions: sessionsQuery.data || [],
    isLoading: sessionsQuery.isLoading,
    error: sessionsQuery.error,
    deleteSession: deleteSessionMutation.mutate,
    isDeleting: deleteSessionMutation.isPending,
    refetch: sessionsQuery.refetch,
  };
};

export const useChatFeedback = () => {
  const queryClient = useQueryClient();

  const feedbackMutation = useMutation({
    mutationFn: ({ 
      sessionId, 
      messageId, 
      feedback,
      rating,
      feedback_text,
      context_tags
    }: { 
      sessionId: string; 
      messageId: string; 
      feedback: 'positive' | 'negative';
      rating?: number;
      feedback_text?: string;
      context_tags?: string[];
    }) =>
      chatAPI.submitFeedback(sessionId, messageId, feedback, rating, feedback_text, context_tags),

    onSuccess: (data) => {
      if (data && typeof data === "object" && (data as { success?: boolean }).success === false) {
        return;
      }
      invalidateFeedbackModeration(queryClient);
    },

    onError: (error) => {
      console.error('❌ Feedback submission failed:', error);
    },
  });

  return {
    submitFeedback: feedbackMutation.mutate,
    isSubmitting: feedbackMutation.isPending,
    feedbackData: feedbackMutation.data,
    feedbackError: feedbackMutation.error,
  };
};
