  const formatRelativeTime = (date: Date): string => {
    const now = new Date();
    const diffInSeconds = Math.floor((now.getTime() - date.getTime()) / 1000);
    
    if (diffInSeconds < 60) {
      return t("chatbot.time.justNow");
    }
    
    const diffInMinutes = Math.floor(diffInSeconds / 60);
    if (diffInMinutes < 60) {
      return t("chatbot.time.minutesAgo", { count: diffInMinutes });
    }
    
    const diffInHours = Math.floor(diffInMinutes / 60);
    if (diffInHours < 24) {
      return t("chatbot.time.hoursAgo", { count: diffInHours });
    }
    
    const diffInDays = Math.floor(diffInHours / 24);
    if (diffInDays < 30) {
      return t("chatbot.time.daysAgo", { count: diffInDays });
    }
    
    const diffInMonths = Math.floor(diffInDays / 30);
    if (diffInMonths < 12) {
      return t("chatbot.time.monthsAgo", { count: diffInMonths });
    }
    
    const diffInYears = Math.floor(diffInMonths / 12);
    return t("chatbot.time.yearsAgo", { count: diffInYears });
  };

