import React, { createContext, useContext, useEffect, useMemo, useState } from "react";
import { en, enGb, es, fr, de, zh, pt, ar, hi } from "./i18n";

type I18nContextValue = {
  locale: string;
  setLocale: (locale: string) => void;
  t: (key: string, params?: Record<string, string | number>) => string;
  availableLocales: Array<{ code: string; name: string; flag: string }>;
};

const I18nContext = createContext<I18nContextValue | undefined>(undefined);

const LOCAL_STORAGE_KEY = "i18n";

export const AVAILABLE_LOCALES = [
  { code: "en", name: "English (US)", flag: "🇺🇸" },
  { code: "en-gb", name: "English (UK)", flag: "🇬🇧" },
  { code: "hi", name: "हिन्दी", flag: "🇮🇳" },
  { code: "es", name: "Español", flag: "🇪🇸" },
  { code: "fr", name: "Français", flag: "🇫🇷" },
  { code: "de", name: "Deutsch", flag: "🇩🇪" },
  { code: "ar", name: "العربية", flag: "🇸🇦" },
  { code: "pt", name: "Português (Brasil)", flag: "🇧🇷" },
  { code: "zh", name: "中文 (简体)", flag: "🇨🇳" },
];

const translations: Record<string, Record<string, string>> = {
  en,
  "en-gb": enGb,
  es,
  fr,
  de,
  zh,
  pt,
  ar,
  hi,
};

function isSupportedLocale(code: string): boolean {
  return AVAILABLE_LOCALES.some((l) => l.code === code);
}

function resolveLocaleFromBrowser(): string | null {
  const browserLang = navigator.language.toLowerCase();
  const exact = AVAILABLE_LOCALES.find((l) => l.code.toLowerCase() === browserLang);
  if (exact) return exact.code;

  const baseLang = browserLang.split("-")[0];
  const baseMatch = AVAILABLE_LOCALES.find((l) => l.code.split("-")[0] === baseLang);
  return baseMatch?.code ?? null;
}

function readInitialLocale(): string {
  try {
    const saved = localStorage.getItem(LOCAL_STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved) as { locale?: string };
      if (parsed.locale && isSupportedLocale(parsed.locale)) {
        return parsed.locale;
      }
    }
  } catch {
    /* fall through */
  }

  return resolveLocaleFromBrowser() ?? "en";
}

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [locale, setLocale] = useState<string>(readInitialLocale);

  useEffect(() => {
    try {
      localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify({ locale }));
      document.documentElement.lang = locale;
    } catch (e) {
    }
  }, [locale]);

  const t = useMemo(() => {
    return (key: string, params?: Record<string, string | number>) => {
      const table = translations[locale] || translations.en;
      let translation = table[key] ?? translations.en[key] ?? key;
      
      if (params) {
        Object.entries(params).forEach(([param, value]) => {
          translation = translation.replace(new RegExp(`{{${param}}}`, 'g'), String(value));
        });
      }
      
      return translation;
    };
  }, [locale]);

  const value: I18nContextValue = useMemo(() => ({ 
    locale, 
    setLocale, 
    t, 
    availableLocales: AVAILABLE_LOCALES 
  }), [locale, t]);

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n(): I18nContextValue {
  const ctx = useContext(I18nContext);
  if (!ctx) throw new Error("useI18n must be used within an I18nProvider");
  return ctx;
}

export function useTranslation() {
  const { t, locale, setLocale, availableLocales } = useI18n();
  
  return {
    t,
    locale,
    setLocale,
    availableLocales,
    isRTL: ['ar', 'he', 'fa', 'ur'].includes(locale.split('-')[0]),
    changeLanguage: setLocale,
  };
}
