              width: '100%',
                  padding: '8px 0.5rem 0.5rem 0.5rem',
              border: `1px solid ${colors.border}`,
                  borderRadius: '0px',
              backgroundColor: colors.background,
              color: colors.foreground,
              fontSize: '12px',
              fontFamily: 'inherit',
              lineHeight: '1.5',
              resize: 'none',
              outline: 'none',
