import React, { useMemo } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import rehypeRaw from "rehype-raw";
import { Prism as SyntaxHighlighter } from "react-syntax-highlighter";
import { oneDark, oneLight } from "react-syntax-highlighter/dist/esm/styles/prism";
import { useTheme } from "@/contexts/ThemeContext";
import { safeStringConversion } from "@/utils/safeStringConversion";
import { prepareStreamingMarkdown } from "@/utils/prepareStreamingMarkdown";

const PROSE_CLASS =
  "text-sm leading-relaxed prose-sm max-w-none prose-headings:text-foreground prose-p:text-foreground prose-strong:text-foreground prose-code:text-foreground prose-pre:bg-muted prose-pre:text-foreground prose-blockquote:text-muted-foreground prose-blockquote:border-l-muted-foreground prose-p:break-words prose-pre:max-w-full";

const CODE_BLOCK_STYLE: React.CSSProperties = {
  margin: 0,
  borderRadius: "0.5rem",
  fontSize: "0.875rem",
  lineHeight: "1.5",
  overflowX: "auto",
  maxWidth: "100%",
  whiteSpace: "pre-wrap",
  wordBreak: "break-word",
};

export type ChatMarkdownVariant = "widget" | "dashboard";

export interface ChatMarkdownProps {
  content: string;
  variant?: ChatMarkdownVariant;
  /** Strips trailing incomplete list markers; safe for finished chat answers too. */
  normalizeMarkdown?: boolean;
  widgetThemeVars?: Record<string, string>;
  widgetCodeTheme?: typeof oneDark;
  className?: string;
  role?: string;
  "aria-label"?: string;
}

export function ChatMarkdown({
  content,
  variant = "dashboard",
  normalizeMarkdown = true,
  widgetThemeVars,
  widgetCodeTheme,
  className,
  role = "text",
  "aria-label": ariaLabel = "Assistant message content",
}: ChatMarkdownProps) {
  const { theme } = useTheme();

  const markdown = useMemo(() => {
    const raw = safeStringConversion(content);
    return normalizeMarkdown ? prepareStreamingMarkdown(raw) : raw;
  }, [content, normalizeMarkdown]);

  const syntaxTheme =
    variant === "widget"
      ? widgetCodeTheme ?? (theme === "dark" ? oneDark : oneLight)
      : theme === "dark"
        ? oneDark
        : oneLight;

  const components = useMemo(
    () => ({
      code: ({ className, children, ...props }: React.ComponentPropsWithoutRef<"code"> & { className?: string }) => {
        const isInline = !className?.includes("language-");
        if (isInline) {
          if (variant === "widget" && widgetThemeVars) {
            return (
              <code
                style={{
                  background: widgetThemeVars["--chatbot-surface"],
                  color: widgetThemeVars["--chatbot-text-color"],
                  padding: "0.125rem 0.25rem",
                  borderRadius: "0.25rem",
                  fontSize: "0.875rem",
                  fontFamily: "monospace",
                }}
                {...props}
              >
                {children}
              </code>
            );
          }
          return (
            <code className="bg-muted px-1 py-0.5 rounded text-sm font-mono" {...props}>
              {children}
            </code>
          );
        }

        const match = /language-(\w+)/.exec(className || "");
        const language = match ? match[1] : "text";

        return (
          <div className="my-4 max-w-full overflow-x-auto">
            <SyntaxHighlighter
              language={language}
              style={syntaxTheme}
              customStyle={CODE_BLOCK_STYLE}
              showLineNumbers={false}
              wrapLines={true}
              wrapLongLines={true}
            >
              {safeStringConversion(children).replace(/\n$/, "")}
            </SyntaxHighlighter>
          </div>
        );
      },
      a: ({ href, children, ...props }: React.ComponentPropsWithoutRef<"a">) => (
        <a
          href={href}
          target="_blank"
          rel="noopener noreferrer"
          className={variant === "widget" ? undefined : "text-primary hover:underline"}
          style={
            variant === "widget"
              ? { color: "var(--chatbot-color)", textDecoration: "underline" }
              : undefined
          }
          {...props}
        >
          {children}
        </a>
      ),
      ul: ({ children, ...props }: React.ComponentPropsWithoutRef<"ul">) => (
        <ul className="list-disc list-outside space-y-1 pl-5" {...props}>
          {children}
        </ul>
      ),
      ol: ({ children, ...props }: React.ComponentPropsWithoutRef<"ol">) => (
        <ol className="list-decimal list-outside space-y-1 pl-5" {...props}>
          {children}
        </ol>
      ),
      blockquote: ({ children, ...props }: React.ComponentPropsWithoutRef<"blockquote">) => (
        <blockquote className="border-l-4 border-muted-foreground pl-4 italic text-muted-foreground" {...props}>
          {children}
        </blockquote>
      ),
    }),
    [variant, widgetThemeVars, syntaxTheme],
  );

  return (
    <div className={className ?? PROSE_CLASS} role={role} aria-label={ariaLabel}>
      <ReactMarkdown remarkPlugins={[remarkGfm]} rehypePlugins={[rehypeRaw]} components={components}>
        {markdown}
      </ReactMarkdown>
    </div>
  );
}
