import { normalizeErrorDetail } from "@/utils/apiKeyErrors";

export type FetchLikeError = Error & {
  response?: { status: number; data: { detail?: string; message?: string } };
};

/** Read JSON/text body from a failed fetch Response (body can only be read once). */
export async function parseHttpErrorDetail(res: Response): Promise<string | undefined> {
  try {
    const text = await res.text();
    if (!text.trim()) return undefined;

    try {
      const data = JSON.parse(text) as {
        detail?: unknown;
        message?: string;
        error?: string;
      };

      const fromDetail = normalizeErrorDetail(data.detail);
      if (fromDetail) return fromDetail;

      if (typeof data.error === "string" && data.error.trim()) {
        return data.error.trim();
      }

      if (typeof data.message === "string" && data.message.trim()) {
        return data.message.trim();
      }

      return text.trim().slice(0, 500);
    } catch {
      return text.trim().slice(0, 500);
    }
  } catch {
    return undefined;
  }
}

/** Throw an axios-shaped error so existing friendly-message helpers can use response.data.detail. */
export async function throwHttpResponseError(
  res: Response,
  fallbackPrefix = "Request failed",
): Promise<never> {
  const detail = await parseHttpErrorDetail(res);
  const message = detail || `${fallbackPrefix} (${res.status})`;
  const err = new Error(message) as FetchLikeError;
  err.response = {
    status: res.status,
    data: { detail: detail ?? message, message: detail },
  };
  throw err;
}
